-- step47: страница «О нас» в новом дизайне.
-- Шаблон «О нас» (категория Redesign) приходит выше в патче (по имени); здесь — доступ к тем же TV, что у «Внутренней» (3),
--   назначение ресурсам RO 102 /despre-noi, RU 298 /ru/o-nas, EN 1102 /en/about-us.
-- Вопросы и ответы страницы (тексты из макета пользователя; RO / EN — перевод) — TV migx_questions (37) и заголовок title-bl-faq (65),
--   как на главной; блок lb-faq выводит их с разметкой FAQPage. Прежних значений у этих ресурсов не было.
-- Откат: UPDATE ... SET template = 3 WHERE id IN (102, 298, 1102); DELETE TV 37 / 65 этих ресурсов.
SET NAMES utf8mb4;
SET @tid := (SELECT id FROM Impulse_Digital_X_site_templates WHERE templatename = 'О нас');
INSERT IGNORE INTO Impulse_Digital_X_site_tmplvar_templates (tmplvarid, templateid, `rank`) SELECT tmplvarid, @tid, `rank` FROM Impulse_Digital_X_site_tmplvar_templates WHERE templateid = 3;
UPDATE Impulse_Digital_X_site_content SET template = @tid WHERE id IN (102, 298, 1102);
DELETE FROM Impulse_Digital_X_site_tmplvar_contentvalues WHERE tmplvarid IN (37, 65) AND contentid IN (102, 298, 1102);
INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES (65, 102, 'Răspunsuri la întrebări frecvente'), (37, 102, '[{"MIGX_id": "1", "questions-title": "Cine efectuează procedurile în studioul Lbar?", "questions-text": "<p>Procedurile sunt efectuate de masteri din două categorii: TOP-Master, cu o experiență de peste 5 ani și certificate internaționale, și TOP-Trainer, master acreditat cu o experiență de peste 8 ani. Fondatoarea studioului este Ksenia Kobilianskaia, Master Trainer internațional.</p>"}, {"MIGX_id": "2", "questions-title": "Cât durează procedura?", "questions-text": "<p>Între o oră și o oră și jumătate, în funcție de zonă. Corecția durează aproximativ o oră.</p>"}, {"MIGX_id": "3", "questions-title": "Pot învăța micropigmentarea la Lbar?", "questions-text": "<p>Da. Școala Lbar a pregătit peste 400 de masteri care lucrează astăzi în mai multe țări. Instruirea se bazează pe metoda proprie PM Control a Kseniei Kobilianskaia.</p>"}, {"MIGX_id": "4", "questions-title": "Unde se află studioul din București?", "questions-text": "<p>Strada Polonă 92, Sector 1, la 4 minute de metroul Ștefan cel Mare. Lucrăm zilnic între 9:00 și 20:00, doar cu programare.</p>"}]');
INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES (65, 298, 'Ответы на <br/>часто задаваемые вопросы'), (37, 298, '[{"MIGX_id": "1", "questions-title": "Кто выполняет процедуры в студии Lbar?", "questions-text": "<p>Процедуры выполняют мастера двух категорий: TOP-Master с опытом более 5 лет и международными сертификатами и TOP-Trainer, аккредитованный мастер с опытом более 8 лет. Основательница студии — Ксения Кобылянская, международный Master Trainer.</p>"}, {"MIGX_id": "2", "questions-title": "Сколько длится процедура?", "questions-text": "<p>От одного до полутора часов, в зависимости от зоны. Коррекция занимает около часа.</p>"}, {"MIGX_id": "3", "questions-title": "Можно ли научиться перманентному макияжу в Lbar?", "questions-text": "<p>Да. Школа Lbar подготовила более 400 мастеров, которые сегодня работают в разных странах. Обучение построено на авторской методике PM Control Ксении Кобылянской.</p>"}, {"MIGX_id": "4", "questions-title": "Где находится студия в Бухаресте?", "questions-text": "<p>Strada Polonă 92, Sector 1, в 4 минутах от метро Ștefan cel Mare. Работаем ежедневно с 9:00 до 20:00, только по записи.</p>"}]');
INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES (65, 1102, 'Answers to frequently asked questions'), (37, 1102, '[{"MIGX_id": "1", "questions-title": "Who performs the procedures at Lbar studio?", "questions-text": "<p>Procedures are performed by masters of two categories: TOP-Master, with more than 5 years of experience and international certificates, and TOP-Trainer, an accredited master with more than 8 years of experience. The studio\'s founder is Ksenia Kobilianskaia, an international Master Trainer.</p>"}, {"MIGX_id": "2", "questions-title": "How long does a procedure take?", "questions-text": "<p>From one to one and a half hours, depending on the area. A touch-up takes about an hour.</p>"}, {"MIGX_id": "3", "questions-title": "Can I learn permanent makeup at Lbar?", "questions-text": "<p>Yes. The Lbar school has trained more than 400 masters who now work in different countries. The training is based on Ksenia Kobilianskaia\'s own PM Control method.</p>"}, {"MIGX_id": "4", "questions-title": "Where is the studio in Bucharest?", "questions-text": "<p>Strada Polonă 92, Sector 1, 4 minutes from Ștefan cel Mare metro station. We work daily from 9:00 to 20:00, by appointment only.</p>"}]');
